// src/bundler/compiler/props-analyzer.ts
class PropsAnalyzer {
  analyzeProps(code) {
    const props = new Map;
    try {
      const propsRegex = /(?:const|export\s+const)\s+props\s*=\s*(?:defineProps\s*)?\{([^}]+)\}/;
      const match = code.match(propsRegex);
      if (!match || !match[1]) {
        return props;
      }
      const propsContent = match[1];
      const propLines = propsContent.split(",").map((line) => line.trim()).filter(Boolean);
      for (const line of propLines) {
        const prop = this.parsePropLine(line);
        if (prop) {
          props.set(prop.name, prop);
        }
      }
    } catch (error) {
      console.warn("Error analyzing props:", error);
    }
    return props;
  }
  parsePropLine(line) {
    const simpleMatch = line.match(/(\w+)\s*:\s*(\w+)/);
    if (simpleMatch) {
      const [, name, type] = simpleMatch;
      return {
        name,
        type: this.normalizeType(type),
        required: false
      };
    }
    const objectMatch = line.match(/(\w+)\s*:\s*\{([^}]+)\}/);
    if (objectMatch) {
      const [, name, content] = objectMatch;
      const typeMatch = content.match(/type\s*:\s*(\w+)/);
      const requiredMatch = content.match(/required\s*:\s*(true|false)/);
      const defaultMatch = content.match(/default\s*:\s*([^,}]+)/);
      return {
        name,
        type: typeMatch ? this.normalizeType(typeMatch[1]) : "any",
        required: requiredMatch ? requiredMatch[1] === "true" : false,
        defaultValue: defaultMatch ? defaultMatch[1].trim() : undefined
      };
    }
    return null;
  }
  normalizeType(type) {
    const normalized = type.toLowerCase();
    if (normalized === "string")
      return "string";
    if (normalized === "number")
      return "number";
    if (normalized === "boolean")
      return "boolean";
    if (normalized === "object")
      return "object";
    if (normalized === "function")
      return "function";
    return "any";
  }
  analyzeSlots(template) {
    const slots = new Map;
    const slotRegex = /<slot(?:\s+name=["'](\w+)["'])?(?:\s+[^>]*)?>([^<]*)<\/slot>/g;
    let match;
    while ((match = slotRegex.exec(template)) !== null) {
      const name = match[1] || "default";
      const fallback = match[2]?.trim();
      slots.set(name, {
        name,
        fallback: fallback || undefined
      });
    }
    return slots;
  }
}

