class SlotsCompiler {
  compileSlots(template, componentName) {
    const slots = this.extractSlots(template);
    const slotsCode = this.generateSlotsCode(slots, componentName);
    const transformedTemplate = this.replaceSlots(template, componentName);
    return { slotsCode, transformedTemplate };
  }
  extractSlots(template) {
    const slots = [];
    const slotRegex = /<slot(?:\s+name=["'](\w+)["'])?(?:\s+[^>]*)?>([^<]*)<\/slot>/g;
    let match;
    while ((match = slotRegex.exec(template)) !== null) {
      const name = match[1] || "default";
      const fallback = match[2]?.trim();
      slots.push({
        name,
        content: fallback || "",
        isDefault: !match[1]
      });
    }
    return slots;
  }
  generateSlotsCode(slots, componentName) {
    if (slots.length === 0)
      return "";
    let code = `// Slots rendering
`;
    code += `const slots = props.__slots || {};
`;
    for (const slot of slots) {
      code += `const slot_${slot.name} = slots.${slot.name} || \`${slot.content}\`;
`;
    }
    return code;
  }
  replaceSlots(template, componentName) {
    return template.replace(/<slot(?:\s+name=["'](\w+)["'])?(?:\s+[^>]*)?>([^<]*)<\/slot>/g, (match, name) => {
      const slotName = name || "default";
      return `<span data-slot="${slotName}">\${slot_${slotName}}</span>`;
    });
  }
  wrapChildrenInSlot(children) {
    if (!children)
      return "";
    return `__slots: { default: ${children} }`;
  }
}

