    "  };",
    "",
    "  ws.onmessage = async (event) => {",
    "    try {",
    "      const data = JSON.parse(event.data);",
    "      switch (data.type) {",
    '        case "connected":',
    '          console.log("%c\u2713 Connected to dev server", "color: #10b981;");',
    "          break;",
    '        case "full-reload":',
    '          console.log("%c\uD83D\uDD04 Reloading page...", "color: #3b82f6;");',
    "          removeOverlay();",
    "          window.location.reload();",
    "          break;",
    '        case "css-update":',
