// src/server/page-compiler.ts
class PageCompiler {
  config;
  scriptParser;
  templateTransformer;
  unifiedParser;
  constructor(config, scriptParser, templateTransformer) {
    this.config = config;
    this.scriptParser = scriptParser;
    this.templateTransformer = templateTransformer;
    this.unifiedParser = new UnifiedParser;
  }
  transformScript(code, stateNames) {
    try {
      if (!code || !code.trim())
        return code;
      const ast = parse3(code, { ecmaVersion: 2020 });
      let magicString = code;
      const replacements = [];
      walk(ast, {
        enter(node, parent2) {
          if (node.type === "Identifier") {
            if (stateNames.has(node.name)) {
              let isSafeToReplace = true;
              if (parent2) {
                if (parent2.type === "MemberExpression" && parent2.property === node && !parent2.computed)
                  isSafeToReplace = false;
                if (parent2.type === "Property" && parent2.key === node && !parent2.computed && !parent2.shorthand)
                  isSafeToReplace = false;
                if (parent2.type === "VariableDeclarator" && parent2.id === node)
                  isSafeToReplace = false;
                if ((parent2.type === "FunctionDeclaration" || parent2.type === "ArrowFunctionExpression") && parent2.params.includes(node))
                  isSafeToReplace = false;
                if (parent2.type === "CallExpression" && parent2.callee === node)
                  isSafeToReplace = false;
                if (parent2.type === "AssignmentExpression" && parent2.left === node)
                  isSafeToReplace = false;
              }
              if (isSafeToReplace) {
                replacements.push({ start: node.start, end: node.end, value: node.name + "()" });
              }
            }
          }
        }
      });
      replacements.sort((a, b) => b.start - a.start);
      for (const rep of replacements) {
        magicString = magicString.slice(0, rep.start) + rep.value + magicString.slice(rep.end);
      }
      return magicString;
    } catch (e) {
      return code;
    }
  }
  async compile(filePath, content2) {
    const ast = this.unifiedParser.parse(content2, filePath);
    let styles = "";
    let logic = "";
    let templateNode = null;
    let template = "";
    if (ast.script.type === "valid") {
      logic = ast.script.code;
    }
    if (ast.styles.type === "valid") {
      styles = ast.styles.code;
    }
    if (ast.template.type === "valid") {
      templateNode = ast.template.ast;
      template = ast.template.code;
    } else {
      templateNode = { type: "element", tag: "root", children: [] };
    }
    const styleTag = styles ? `<style>${styles}</style>` : "";
    const scriptResult = this.scriptParser.parse(logic);
    const isInteractive = scriptResult.stateVars.length > 0 || scriptResult.functions.length > 0 || scriptResult.imports.length > 0 || scriptResult.declarations.length > 0;
    if (isInteractive) {
      if (!templateNode)
        throw new Error("Template Node missing");
      return this.compileInteractive(templateNode, template, scriptResult, styleTag, filePath);
    } else {
      return this.compileStatic(template, styleTag);
    }
  }
  compileInteractive(templateNode, template, scriptResult, styleTag, filePath) {
    const pageName = path8.basename(filePath, ".pulse");
    const imports = [];
    const pageDir = path8.dirname(filePath);
    scriptResult.imports.forEach((imp) => {
      const resolvedPath = path8.resolve(pageDir, imp.source);
      imp.names.forEach((n) => {
        imports.push({ name: n, path: imp.source, resolvedPath });
      });
    });
    const { stateVars, functions, declarations, computedVars } = scriptResult;
    const stateNames = new Set(stateVars.map((v) => v.name));
    const transformedFunctions = functions.map((fn) => ({
      ...fn,
      code: this.transformScript(fn.code || "", stateNames)
    }));
    const transformedComputed = computedVars.map((cv) => ({
      ...cv,
      code: this.transformScript(cv.code || "", stateNames)
    }));
    const transformedDeclarations = declarations.map((d) => ({
      ...d,
      code: this.transformScript(d.code || "", stateNames)
    }));
    const hasListPrimitive = template.includes("<List") || template.includes("data-pulse-list");
    const hasShowPrimitive = template.includes("<Show") || template.includes("data-pulse-show");
    const primitiveImports = [];
    if (hasListPrimitive && !imports.some((i2) => i2.name === "List")) {
      primitiveImports.push("import { List } from '/runtime/primitives/list.js';");
    }
    if (hasShowPrimitive && !imports.some((i2) => i2.name === "Show")) {
      primitiveImports.push("import { Show } from '/runtime/primitives/show.js';");
    }
    const componentNames = imports.map((i2) => i2.name).filter((n) => /^[A-Z]/.test(n));
    const stateVarsWithSetters = stateVars.map((sv) => ({
      ...sv,
      setter: sv.setterName || "set" + sv.name.charAt(0).toUpperCase() + sv.name.slice(1)
    }));
    const { html, bindings, templates } = this.templateTransformer.transform(templateNode, [...stateVarsWithSetters, ...computedVars], componentNames, declarations);
    const mountScript = getMountScript(imports, hasListPrimitive, hasShowPrimitive);
    const handlerEntries = [
      ...functions.map((f) => `${f.name}: ${f.name}`),
      ...stateVars.map((sv) => {
        const setterName = sv.setterName || "set" + sv.name.charAt(0).toUpperCase() + sv.name.slice(1);
        return `${setterName}: ${setterName}`;
      })
    ];
    const handlersString = handlerEntries.join(`,
    `);
    const scopeProperties = [
      ...stateVars.map((s) => `${s.name}: ${s.name}`),
      ...stateVars.map((sv) => {
        const setterName = sv.setterName || "set" + sv.name.charAt(0).toUpperCase() + sv.name.slice(1);
        return `${setterName}: ${setterName}`;
      }),
      ...computedVars.map((c) => `${c.name}: ${c.name}`),
      ...functions.map((f) => `${f.name}: ${f.name}`),
      ...declarations.map((d) => `${d.name}: ${d.name}`),
      "...components"
    ];
    const scopePropsString = scopeProperties.join(`,
    `);
    const importMap = {
      imports: {
        pulse: "/runtime/core.js",
        "pulse/dom": "/runtime/dom.js",
        "pulse/list": "/runtime/primitives/list.js",
        "pulse/show": "/runtime/primitives/show.js"
      }
    };
    return wrapHTML(`
${styleTag}
<div id="app-${pageName}">
  ${html}
</div>

<script type="module">
import { createSignal, createEffect, createMemo } from 'pulse';
import { mountPrimitives as mountPrimitives_dom } from 'pulse/dom';
${primitiveImports.map((i2) => i2.replace("'/runtime/primitives/list.js'", "'pulse/list'").replace("'/runtime/primitives/show.js'", "'pulse/show'")).join(`
`)}
${imports.map((imp) => `import ${imp.name} from '/__component?path=${encodeURIComponent(imp.resolvedPath)}';`).join(`
`)}

(function() {
  const root = document.getElementById('app-${pageName}');
  if (!root) return;
  
  // Data declarations
  ${transformedDeclarations.map((d) => d.code).join(`
  `)}
  
  // Create reactive state (Signals)
  ${stateVars.map(({ name: name2, value: value2, setterName }) => {
      const setter = setterName || "set" + name2.charAt(0).toUpperCase() + name2.slice(1);
      return `const [${name2}, ${setter}] = createSignal(${value2});`;
    }).join(`
  `)}
  
  // Computed Variables
  ${transformedComputed.map((cv) => cv.code).join(`
  `)}

  // Define functions
  ${transformedFunctions.map((fn) => fn.code).join(`

`)}

  // Components map
  const components = {
    ${componentNames.join(`,
    `)}
  };

  // Templates map
  const templates = new Map([
    ${Array.from(templates.entries()).map(([k, v]) => `['${k}', ${JSON.stringify(v)}]`).join(`,
    `)}
  ]);

  // Scope construction for hydration
  const scope = {
    ${scopePropsString}
  };

  // Mount Components and Primitives
  ${mountScript}

  // Setup reactive bindings
  const unescapeHtml = (str) => str.replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&amp;/g, '&').replace(/&quot;/g, '"');
  ${bindings.map((binding) => {
      const expr = binding.expression.replace(/&gt;/g, ">").replace(/&lt;/g, "<").replace(/&amp;/g, "&");
      if (binding.type === "text") {
        return `
  createEffect(() => {
    const el = root.querySelector('[data-bind="${binding.targetId}"]');
    if (el) el.textContent = ${expr};
  });`;
      } else {
        const isBoolean = binding.name === "checked" || binding.name === "disabled";
        const isValue2 = binding.name === "value";
        if (isBoolean || isValue2) {
          return `
  createEffect(() => {
    const el = root.querySelector('[data-pulse-id="${binding.targetId}"]');
    if (el) el.${binding.name} = ${binding.expression.replace(/&gt;/g, ">").replace(/&lt;/g, "<").replace(/&amp;/g, "&")};
  });`;
        } else {
          return `
  createEffect(() => {
    const el = root.querySelector('[data-pulse-id="${binding.targetId}"]');
    if (el) el.setAttribute('${binding.name}', ${binding.expression.replace(/&gt;/g, ">").replace(/&lt;/g, "<").replace(/&amp;/g, "&")});
  });`;
        }
      }
    }).join(`
`)}
  
  // Hydrate the app root (DOM + Components)
  // 'hydrate' is defined in the mount script and handles both hydrateDOM and mountPrimitives
  hydrate(root);

  
})();
</script>
      `, pageName, getHMRScript(this.config), importMap);
  }
  compileStatic(template, styleTag) {
    const html = `${styleTag}
${template}`;
    return wrapHTML(html, "Pulse App", getHMRScript(this.config));
  }
  serializeNode(node) {
    if (node.type === "comment")
      return `<!--${node.content}-->`;
    if (node.type === "text")
      return node.content || "";
    if (node.type === "expression")
      return `{${node.content}}`;
    if (node.type === "element") {
      let attrs = "";
      if (node.attributes) {
        node.attributes.forEach((val, key) => {
          if (typeof val === "string") {
            attrs += ` ${key}="${val.replaceAll('"', "&quot;")}"`;
          } else {
            attrs += ` ${key}={${val.code}}`;
          }
        });
      }
      const children2 = node.children ? node.children.map((c) => this.serializeNode(c)).join("") : "";
      const voidElements = new Set(["area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"]);
      if (node.tag && voidElements.has(node.tag.toLowerCase()) && !children2) {
        return `<${node.tag}${attrs} />`;
      }
      return `<${node.tag}${attrs}>${children2}</${node.tag}>`;
    }
    return "";
  }
}

// src/server/dev-server.ts
class DevServer {
  hmr;
  config;
  ssr;
  server;
  moduleGraph;
  cache;
  watcher;
  analyzer;
  compiler;
  safeCompiler;
  pageCompiler;
  lastError;
  hotReload;
  reactivityTransformer;
  compiledComponents;
  scriptParser;
  templateTransformer;
  constructor(config) {
    this.config = config;
    this.hmr = new HMRManager;
    this.scriptParser = new ScriptParser;
    this.moduleGraph = new ModuleGraph;
    this.cache = new CompilationCache;
    this.watcher = new FileWatcher;
    this.analyzer = new DependencyAnalyzer(config);
    this.hotReload = new HotReload(this.moduleGraph, this.hmr);
    this.templateTransformer = new TemplateTransformer;
    this.pageCompiler = new PageCompiler(config, this.scriptParser, this.templateTransformer);
    this.compiler = new ComponentCompiler(config, this.scriptParser, this.templateTransformer);
    this.ssr = new SSRRenderer(config, this.compiler);
    this.safeCompiler = new SafeCompiler(this.compiler);
    this.reactivityTransformer = new ReactivityTransformer;
    this.compiledComponents = new Map;
  }
  async start() {
    const port = this.config.devServer.port;
    this.server = Bun.serve({
      port,
      fetch: async (req, server) => {
        const url2 = new URL(req.url);
        if (url2.pathname === "/__pulse_hmr") {
          const upgraded = server.upgrade(req);
          if (upgraded)
            return;
          return new Response("Upgrade failed", { status: 500 });
        }
        if (url2.pathname === "/__pulse_client.js") {
          return serveHMRClient();
        }
        if (url2.pathname.startsWith("/runtime/")) {
          return await this.serveRuntime(url2.pathname);
        }
        if (url2.pathname === "/__component") {
          const filePath = url2.searchParams.get("path");
          if (filePath)
            return await this.serveComponentByPath(filePath);
          return new Response("Missing path parameter", { status: 400 });
        }
        if (url2.pathname.startsWith("/components/")) {
          return await this.serveComponent(url2.pathname);
        }
        if (url2.pathname.startsWith("/__modules/")) {
          return await this.serveModule(url2.pathname);
        }
        if (url2.pathname.startsWith("/public/")) {
          return await this.servePublic(url2.pathname);
        }
        return await this.servePage(url2.pathname);
      },
      websocket: {
        open: (ws) => this.hmr.addClient(ws),
        message: (ws, message) => {
          try {
            const data3 = JSON.parse(message.toString());
            this.handleClientMessage(ws, data3);
          } catch (error2) {}
        },
        close: (ws) => this.hmr.removeClient(ws)
      }
    });
    this.startFileWatcher();
    console.log(`
\u26A1 Pulse v0.16.0 Dev Server running
`);
    console.log(`  Local:    http://localhost:${port}`);
    console.log(`  Network:  http://0.0.0.0:${port}`);
    console.log(`  HMR:      ${this.config.devServer.hmr ? "\u2713 Enabled" : "\u2717 Disabled"}`);
    console.log(`  Cache:    \u2713 Enabled`);
    console.log(`
  Ready in ${process.uptime().toFixed(0)}ms
`);
  }
  async servePage(pathname) {
    try {
      if (this.lastError) {
        this.lastError = undefined;
        this.hmr.clearError();
      }
      const pagesDir = path9.resolve(this.config.root, this.config.pages.dir);
      let pagePath;
      if (pathname === "/") {
        pagePath = path9.join(pagesDir, "index.pulse");
      } else {
        const cleanPath = pathname.slice(1);
        if (cleanPath.endsWith("/")) {
          pagePath = path9.join(pagesDir, cleanPath.slice(0, -1) + ".pulse");
        } else {
          pagePath = path9.join(pagesDir, cleanPath + ".pulse");
        }
        const indexPath = path9.join(pagesDir, cleanPath, "index.pulse");
        const indexFile = Bun.file(indexPath);
        if (await indexFile.exists()) {
          pagePath = indexPath;
        }
      }
      const file = Bun.file(pagePath);
      if (!await file.exists()) {
        return serve404(pathname);
      }
      this.moduleGraph.addModule(pagePath, "page");
      console.log(`\uD83D\uDD28 SSR Compiling: ${path9.basename(pagePath)}`);
      const ssrHtml = await this.ssr.renderPage(pagePath);
      const pageBasename = path9.basename(pagePath);
      const relativePageUrl = pathname === "/" ? "/index.pulse" : pathname + (pathname.endsWith(".pulse") ? "" : ".pulse");
      const relativePath = path9.relative(this.config.root, pagePath);
      const clientModuleUrl = `/__modules/${relativePath}`;
      const clientScript = `
        <script type="module">
          import Page from '${clientModuleUrl}';
          import { hydrate } from '/runtime/dom.js';
          
          const app = document.getElementById('app');
          hydrate(Page, app);
          
          // HMR Support
          if (import.meta.hot) {
            import.meta.hot.accept(() => {
              window.location.reload();
            });
          }
        </script>
      `;
      const fullHtml = this.ssr.wrapHTML(`
        <div id="app">${ssrHtml}</div>
        ${clientScript}
      `);
      return new Response(fullHtml, {
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "X-Pulse-Page": pageBasename,
          "Cache-Control": "no-cache, no-store, must-revalidate"
        }
      });
    } catch (error2) {
      console.error("\u274C Error serving page:", error2.message);
      if (error2 instanceof ComponentPropsError || error2 instanceof ComponentImportError) {
        this.lastError = error2.toDevError();
      } else {
        this.lastError = {
          type: "compile",
          file: pathname,
          message: error2.message,
          stack: error2.stack,
          suggestion: generateSuggestion(error2)
        };
      }
      const devError = this.lastError;
      this.hmr.error(devError);
      return new Response(ErrorOverlay.generateHTML(devError), {
        status: 500,
        headers: { "Content-Type": "text/html; charset=utf-8" }
      });
    }
  }
  async serveRuntime(pathname) {
    const runtimePath = pathname.replace("/runtime/", "");
    let frameworkRuntimeDir = path9.resolve(import.meta.dir, "../runtime");
    const coreCheck = Bun.file(path9.join(frameworkRuntimeDir, "core.ts"));
    if (!await coreCheck.exists()) {
      frameworkRuntimeDir = path9.resolve(import.meta.dir, "../../src/runtime");
    }
    const serveTsFile = async (fileName) => {
      const filePath = path9.join(frameworkRuntimeDir, fileName);
      const file = Bun.file(filePath);
      if (await file.exists()) {
        const content2 = await file.text();
        const transpiler = new Bun.Transpiler({ loader: "ts" });
        const js = await transpiler.transform(content2);
        return new Response(js, {
          headers: {
            "Content-Type": "application/javascript",
            "Cache-Control": "no-cache, no-store, must-revalidate"
          }
        });
      }
      return new Response(`console.error("Runtime file ${fileName} not found at ${filePath}")`, { status: 404 });
    };
    if (runtimePath === "core.js") {
      return await serveTsFile("core.ts");
    }
    if (runtimePath === "primitives/list.js") {
      return await serveTsFile("primitives/list.ts");
    }
    if (runtimePath === "primitives/show.js") {
      return await serveTsFile("primitives/show.ts");
    }
    if (runtimePath === "dom.js") {
      return await serveTsFile("dom.ts");
    }
    return new Response('console.error("Runtime file not found")', { status: 404 });
  }
  async serveComponent(pathname) {
    try {
      const cleanPathname = pathname.endsWith(".js") ? pathname.slice(0, -3) : pathname;
      const componentPath = path9.join(this.config.root, cleanPathname);
      let file = Bun.file(componentPath);
      let foundPath = componentPath;
      if (!await file.exists()) {
        const srcPath = path9.join(this.config.root, "src", cleanPathname);
        file = Bun.file(srcPath);
        if (await file.exists()) {
          foundPath = srcPath;
        } else {
          return new Response('console.error("Component not found")', { status: 404 });
        }
      }
      const content2 = await file.text();
      const hash = this.cache.computeHash(content2);
      let compiled = this.compiledComponents.get(foundPath);
      if (!compiled || !this.cache.get(foundPath, hash)) {
        console.log(`\uD83D\uDD28 Compiling component: ${path9.basename(foundPath)}`);
        const result2 = await this.safeCompiler.compile(content2, foundPath);
        if (result2.isOk()) {
          compiled = result2.value.code;
          this.compiledComponents.set(foundPath, compiled);
          this.cache.set(foundPath, hash, compiled, []);
        } else {
          const err = result2.error;
          throw err;
        }
      }
      return new Response(compiled, {
        headers: {
          "Content-Type": "application/javascript",
          "Cache-Control": "no-cache, no-store, must-revalidate"
        }
      });
    } catch (error2) {
      console.error("Component serve error:", error2);
      return new Response(`console.error("Component serve error: ${error2.message}")`, {
        status: 500,
        headers: { "Content-Type": "application/javascript" }
      });
    }
  }
  async serveComponentByPath(filePath) {
    try {
      const file = Bun.file(filePath);
      if (!await file.exists()) {
        return new Response("Component not found", { status: 404 });
      }
      const content2 = await file.text();
      const hash = this.cache.computeHash(content2);
      let compiled = this.compiledComponents.get(filePath);
      if (!compiled || !this.cache.get(filePath, hash)) {
        console.log(`\uD83D\uDD28 Compiling component: ${path9.basename(filePath)}`);
        const result2 = await this.safeCompiler.compile(content2, filePath);
        if (result2.isOk()) {
          compiled = result2.value.code;
          this.compiledComponents.set(filePath, compiled);
          this.cache.set(filePath, hash, compiled, []);
        } else {
          const err = result2.error;
          throw err;
        }
      }
      return new Response(compiled, {
        headers: {
          "Content-Type": "application/javascript",
          "Cache-Control": "no-cache, no-store, must-revalidate"
        }
      });
    } catch (error2) {
      console.error("Component serve error:", error2);
      return new Response(this.generateErrorComponent(error2, filePath), {
        headers: { "Content-Type": "application/javascript" }
      });
    }
  }
  async serveModule(pathname) {
    const modulePath = pathname.replace("/__modules/", "");
    const srcPath = path9.join(this.config.root, modulePath);
    const file = Bun.file(srcPath);
    if (!await file.exists()) {
      return new Response('console.error("Module not found")', { status: 404 });
    }
    if (modulePath.endsWith(".pulse")) {
      const content2 = await file.text();
      const result2 = await this.safeCompiler.compile(content2, srcPath);
      if (result2.isOk()) {
        const compiled = result2.value.code;
        return new Response(compiled, {
          headers: { "Content-Type": "application/javascript" }
        });
      } else {
        const err = result2.error;
        console.error("Module compilation error:", err);
        return new Response(`console.error("Module compilation error: ${err.message}")`, {
          status: 500,
          headers: { "Content-Type": "application/javascript" }
        });
      }
    }
    return new Response(file);
  }
  async servePublic(pathname) {
    const publicPath = path9.join(this.config.root, pathname);
    const file = Bun.file(publicPath);
    if (await file.exists()) {
      return new Response(file);
    }
    return new Response("Not Found", { status: 404 });
  }
  generateErrorComponent(error2, path10) {
    return `
      export default function ErrorComponent() {
        const el = document.createElement('div');
        el.style.cssText = 'border: 2px solid red; padding: 20px; margin: 10px; background: #fff0f0; border-radius: 8px; font-family: monospace;';
        el.innerHTML = \`
          <h3 style="color: #d32f2f; margin-top: 0;">\u26A0\uFE0F Component Error</h3>
          <p><strong>File:</strong> ${path10}</p>
          <div style="background: #ffebee; padding: 10px; border-radius: 4px; overflow-x: auto;">
            <p style="margin: 0; color: #b71c1c;"><strong>Error:</strong> ${error2.message.replace(/`/g, "\\`")}</p>
          </div>
          <pre style="margin-top: 10px; font-size: 11px; color: #555;">${(error2.stack || "").replace(/`/g, "\\`")}</pre>
        \`;
        return el;
      }
    `;
  }
  startFileWatcher() {
    this.watcher.watch(this.config.root, {
      recursive: true,
      ignored: ["**/node_modules/**", "**/.git/**", "**/dist/**"],
      extensions: [".pulse", ".ts", ".css", ".js"]
    }, (event) => {
      const filePath = event.file;
      console.log(`\uD83D\uDCDD File ${event.type}: ${path9.basename(filePath)}`);
      this.cache.invalidate(filePath);
      if (this.config.devServer.hmr) {
        if (filePath.endsWith(".css")) {
          this.hmr.broadcast({ type: "css-update", path: "/" + path9.relative(this.config.root, filePath) });
        } else {
          this.hmr.broadcast({ type: "full-reload" });
        }
      }
    });
  }
  handleClientMessage(ws, data3) {
    if (data3.type === "ping") {
      ws.send(JSON.stringify({ type: "pong", timestamp: Date.now() }));
    }
  }
  stop() {
    this.watcher.close();
    this.server?.stop();
    console.log(`
\uD83D\uDC4B Dev server stopped
`);
  }
}

